import{_ as e,c as t,o as s,H as n}from"./chunks/framework.B03ETCDl.js";const d=JSON.parse('{"title":"Amazon ECS 초심자가 알아야할 것들","description":"","frontmatter":{"title":"Amazon ECS 초심자가 알아야할 것들","date":"2024-11-11T23:00+09:00","tags":["Amazon ECS"]},"headers":[],"relativePath":"posts/aws-ecs.md","filePath":"posts/aws-ecs.md","lastUpdated":1779712000000}'),r={name:"posts/aws-ecs.md"};function o(i,a,l,h,c,p){return s(),t("div",null,[...a[0]||(a[0]=[n(`<p>Amazon ECS로 컨테이너 운용을 위한 환경을 구축해보니 생각보다 러닝커브가 높습니다. Amazon ECS 경험이 부족한 초심자로써 알아야할 것들에 대해서 공유해보고자 한다.</p><h5 id="오토스케일링-그룹-과-amazon-ecs-최적화-linux-ami" tabindex="-1">오토스케일링 그룹 과 Amazon ECS 최적화 Linux AMI <a class="header-anchor" href="#오토스케일링-그룹-과-amazon-ecs-최적화-linux-ami" aria-label="Permalink to &quot;오토스케일링 그룹 과 Amazon ECS 최적화 Linux AMI&quot;">​</a></h5><p>Amazon ECS는 EC2 인스턴스 기반 구성을 위해서는 시작 템플릿으로 정의된 오토스케일링 그룹(ASG)을 용량 공급자로 추가하고 오토스케일링 정의에 따라 실행된 ECS 인스턴스 내에 ECS 에이전트와 통신하여 태스크를 컨테이너로 실행한다. 오토스케일링 그룹으로 실행되는 인스턴스는 <a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/ecs-optimized_AMI.html" target="_blank" rel="noreferrer">Amazon ECS 최적화 Linux AMI</a>로 구성되어야 한다.</p><blockquote><p>Amazon ECS 최적화 Linux AMI를 사용해야하는 이유는 Amazon ECS 컨테이너 에이전트(ecs-agent)가 포함되어있기 때문입니다. ECS 클러스터가 태스크로 실행되는 컨테이너를 관리하기 위해서는 ecs-agent 컨테이너와 통신해야 합니다.</p></blockquote><p>ECS 클러스터 생성 시 EC2 용량 공급자를 생성하지 않은 경우 별도로 오토스케일링 그룹을 만들고 추가해야한다. 이때 오토스케일링 그룹의 시작 템플릿에 사용자 데이터 항목으로 <a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/bootstrap_container_instance.html" target="_blank" rel="noreferrer">Amazon ECS 컨테이너 에이전트 구성(ECS_CLUSTER)</a>을 지정해야한다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/bash</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ECS_CLUSTER=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$CLUSTER_NAME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/ecs/ecs.config</span></span></code></pre></div><h4 id="애플리케이션-속성을-위한-s3-환경-변수-파일-권한" tabindex="-1">애플리케이션 속성을 위한 S3 환경 변수 파일 권한 <a class="header-anchor" href="#애플리케이션-속성을-위한-s3-환경-변수-파일-권한" aria-label="Permalink to &quot;애플리케이션 속성을 위한 S3 환경 변수 파일 권한&quot;">​</a></h4><p>태스크 실행 역할(Task Execution Role)에는 <a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/use-environment-file.html" target="_blank" rel="noreferrer">환경 변수 파일</a>이 저장된 S3 버킷에 대한 권한을 포함하고 있어야한다. 처음 ECS 클러스터를 구성하는 경우 AmazonS3ReadOnlyAccess 정책을 포함하여 테스트해도 된다. 더 나아가 외부 시스템에 대한 토큰이나 데이터베이스 비밀번호와 같은 민감한 정보들은 환경 변수 파일 대신에 Secrets Manager 또는 AWS Systems Manager Parameter Store 에서 가져오는 걸 권장한다.</p><h4 id="amazon-ecs-로그를-cloudwatch로-전송" tabindex="-1">Amazon ECS 로그를 CloudWatch로 전송 <a class="header-anchor" href="#amazon-ecs-로그를-cloudwatch로-전송" aria-label="Permalink to &quot;Amazon ECS 로그를 CloudWatch로 전송&quot;">​</a></h4><p>Amazon ECS 컨테이너에서 발생하는 로그를 CloudWatch로 전송하여 확인하고자 한다면 태스크 정의 시 <a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/using_awslogs.html" target="_blank" rel="noreferrer">awslogs 로그 드라이버를 설정해야</a>한다. 또한, Amazon ECS 컨테이너 인스턴스 역할(AmazonEC2ContainerServiceforEC2Role 정책을 가진 ecsInstanceRole)에 CloudWatch로 로그를 전송하기 위한 권한이 포함되어있는지 확인해야한다.</p><h4 id="ecs-태스크-컨테이너-헬스-체크" tabindex="-1">ECS 태스크 컨테이너 헬스 체크 <a class="header-anchor" href="#ecs-태스크-컨테이너-헬스-체크" aria-label="Permalink to &quot;ECS 태스크 컨테이너 헬스 체크&quot;">​</a></h4><p>태스크 정의 시 <a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/healthcheck.html" target="_blank" rel="noreferrer">컨테이너 상태 확인 옵션을 구성</a>할 수 있는데 이 상태 확인은 __컨테이너 내부__에서 실행된다. 그래서 일반적인 예시는 아래와 같이 로컬호스트로 설명하는데 직접 만드는 애플리케이션 이미지의 경우 애플리케이션이 실행되어 사용하는 포트를 명확히 지정할 필요가 있다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">CMD-SHELL,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:5000/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> exit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span></code></pre></div><h4 id="amazon-ecs-service-connect-컨테이너로-인한-배포-이슈" tabindex="-1">Amazon ECS Service Connect 컨테이너로 인한 배포 이슈 <a class="header-anchor" href="#amazon-ecs-service-connect-컨테이너로-인한-배포-이슈" aria-label="Permalink to &quot;Amazon ECS Service Connect 컨테이너로 인한 배포 이슈&quot;">​</a></h4><p>Amazon ECS 에서 Fargate 또는 EC2 인스턴스에 태스크 컨테이너를 배포하는 경우 ECS 에이전트에 대한 컨테이너와 서비스 옵션에 따라 <a href="https://youtu.be/QA3tnyLvj2A?t=408" target="_blank" rel="noreferrer">서비스 연결을 위해</a> 사이드카로 Envoy 기반의 컨테이너가 함께 구동될 수 있다. 이 말은 하나의 서버 내에 애플리케이션에 대한 컨테이너 뿐만 아니라 나머지 컨테이너가 사용하는 CPU와 메모리를 고려하여 인스턴스 사양을 고려해야한다는 것이다.</p><blockquote><p>처음에는 ECS 클러스터의 서버 사양을 최대한 낮추어 만들게 된 상태에서 서비스 연결을 위한 Instance Connect 컨테이너가 구동되면서 CPU 사용량이 100프로를 넘어서면서 배포가 원활하지 않은 상황을 경험했습니다.</p></blockquote><h4 id="amazon-ecs에-대한-fargate-컨테이너-이미지-최적화-고려" tabindex="-1">Amazon ECS에 대한 Fargate 컨테이너 이미지 최적화 고려 <a class="header-anchor" href="#amazon-ecs에-대한-fargate-컨테이너-이미지-최적화-고려" aria-label="Permalink to &quot;Amazon ECS에 대한 Fargate 컨테이너 이미지 최적화 고려&quot;">​</a></h4><p>Fargate 서버에서 실행되는 태스크 컨테이너는 이미지 정보를 캐싱하지 않는다. 따라서, Fargate 태스크를 시작하는데 걸리는 시간에는 이미지를 가져오는 시간이 포함되어있다. EC2 용량 공급자가 아닌 Fargate로 운용하는 서비스의 경우에는 아래의 항목을 고려해볼 필요가 있다.</p><ul><li><a href="https://docs.aws.amazon.com/AmazonECR/latest/userguide/vpc-endpoints.html" target="_blank" rel="noreferrer">Amazon ECR 인터페이스 VPC 엔드포인트(AWS PrivateLink)</a></li><li><a href="https://docs.aws.amazon.com/ko_kr/linux/al2023/ug/minimal-container.html" target="_blank" rel="noreferrer">Amazon Linux 2023 최소 컨테이너 이미지</a></li><li><a href="https://aws.amazon.com/ko/blogs/containers/reducing-aws-fargate-startup-times-with-zstd-compressed-container-images/" target="_blank" rel="noreferrer">zstd 압축 컨테이너 이미지를 사용</a></li></ul><h2 id="참고-링크" tabindex="-1">참고 링크 <a class="header-anchor" href="#참고-링크" aria-label="Permalink to &quot;참고 링크&quot;">​</a></h2><ul><li><a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/ecs-tutorials.html" target="_blank" rel="noreferrer">Amazon ECS에 관한 자습서</a></li><li><a href="https://ecsworkshop.com/" target="_blank" rel="noreferrer">Amazon ECS Workshop</a></li><li><a href="https://youtu.be/wxyyUrWVBZA?si=9b6PR9gt8KHCDVgf&amp;t=1079" target="_blank" rel="noreferrer">AWS에서 Container 시작하기</a></li><li><a href="https://www.youtube.com/watch?v=_wyndTR95fU" target="_blank" rel="noreferrer">Amazon ECS를 통한 도커 기반 컨테이너 서비스 구축하기</a></li><li><a href="https://www.youtube.com/watch?v=QA3tnyLvj2A&amp;t=408s" target="_blank" rel="noreferrer">Amazon ECS Service Connect 사용하기</a></li><li><a href="https://docs.aws.amazon.com/ko_kr/AmazonECS/latest/developerguide/ecs-configuration.html" target="_blank" rel="noreferrer">Amazon ECS를 위한 솔루션 설계</a></li></ul>`,21)])])}const k=e(r,[["render",o]]);export{d as __pageData,k as default};
